-- Dansk portion 3 del 3/3: 166 MC-spørgsmål på sværhedsskalaen 1-10.000, niveau 6583-9980.
-- Del af de 5.000 nye danskopgaver. Skrevet fra bunden til dansk folkeskole, 3.-9. klasse.
-- Genereret af tools/questions/build-danish-5000.mjs; ret i tools/questions/fixtures/danish-5000/, ikke her.
-- Kræver migration A (20261020120000_difficulty_scale_a): kolonnen questions.difficulty_level.
--
-- Niveau: hver opgave har et eksplicit difficulty_level (forfatterens skøn, ikke en måling).
-- target_grade/difficulty_band er afledt baglæns af niveauet (cellen i §4.1).
--
-- INAKTIV VED INDSÆTTELSEN: alle rækker får is_active=false og metadata.level_batch='danish3'.
-- Aktivering er en SEPARAT migration efter dokumenteret stikprøvekontrol og særskilt ejergodkendelse.
-- Må KUN anvendes via apply_migration med særskilt ejer-autorisation (D-110).

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band, difficulty_level)
SELECT
  jsonb_build_object('question', e->>'q', 'options', e->'o', 'correct', e->>'a',
                     'accepted_answers', jsonb_build_array(e->>'a'), 'review_text', e->>'r'),
  'mc', 'short',
  jsonb_build_object('concepts', jsonb_build_array(m.concept), 'cognitive_skill', m.skill,
                     'difficulty_type', m.dtype, 'misconception_type', m.mis,
                     'challenge_role', e->>'role', 'insight_type', e->>'insight',
                     'practice_variant', e->>'variant',
                     'level_batch', 'danish3', 'domain', 'danish'),
  'mc_single', (e->>'b')::int, 'auto', false, 'danish', (e->>'g')::int,
  (e->>'b')::int, (e->>'l')::int
FROM jsonb_array_elements($$[
{"l":6583,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilket forfatternavn brugte Karen Blixen på sine bøger på engelsk?","o":["Peter Rung","Anders Krogh","Isak Dinesen","Martin Holm"],"a":"Isak Dinesen","r":"Karen Blixen udgav på engelsk under navnet Isak Dinesen. Dinesen var hendes pigenavn."},
{"l":6604,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find ordet: 'Før fremlæggelsen var Malthe så ___, at hans hænder rystede.'","o":["nervøss","nærvøs","nervos","nervøs"],"a":"nervøs","r":"Ordet kommer af 'nerve', så det har e, og det ender på -øs med ét s."},
{"l":6629,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Hvis alarmen lyder, går alle roligt ud ad nærmeste udgang. Tag ikke tasker med. Elever i idrætssalen går ud ad den sorte dør og mødes ved flagstangen.' Hvad får man ikke at vide?","o":["Hvor elever fra andre lokaler skal mødes","Hvilken dør eleverne i idrætssalen skal bruge","Om man må tage sin taske med ud","Hvordan man skal bevæge sig ud af bygningen"],"a":"Hvor elever fra andre lokaler skal mødes","r":"Mødestedet nævnes kun for elever i idrætssalen. Det er ikke det samme som, at det gælder for alle."},
{"l":6648,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Han indvendte, at det var for dyrt.' Hvordan var bemærkningen ment?","o":["som en ros","som et modargument","som en vittighed","som et spørgsmål"],"a":"som et modargument","r":"En indvending er en bemærkning imod det, der er foreslået. Den peger på en svaghed i forslaget."},
{"l":6669,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Jeg skal til ___ og klippes i morgen.'","o":["frissør","frizør","frisør","friisør"],"a":"frisør","r":"Ordet stammer fra fransk og skrives med ét s og endelsen -ør."},
{"l":6686,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken form passer: 'Hun afleverede et ___ svar på et stykke papir.'?","o":["skrevne","skrive","skriver","skrevet"],"a":"skrevet","r":"Foran et intetkønsord i ental står kort tillægsform i grundformen 'skrevet'. 'Skrevne' er flertal eller bestemt form."},
{"l":6706,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Da vi nu alle er enige om, at skolens toiletter er en skandale, må spørgsmålet være, hvem der skal betale.' Hvad gør skribenten med sætningens første del?","o":["Hun lader, som om sagen er afgjort, uden at vise det","Hun spørger forsigtigt, om nogen er uenige med hende","Hun giver eksempler på, hvad der er galt med toiletterne","Hun afviser, at der er et problem med toiletterne"],"a":"Hun lader, som om sagen er afgjort, uden at vise det","r":"Ordene 'da vi nu alle er enige' springer diskussionen over. Læseren bliver regnet med, før der er givet et eneste argument."},
{"l":6728,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Jeg skulle have sagt noget. Det ved jeg nu. Dengang så jeg bare ned på mine sko, mens de andre grinede af Mia, og bagefter sagde jeg til mig selv, at det ikke var min sag.' Hvad føler fortælleren nu?","o":["Vrede over, at Mia grinede af fortælleren","Skyld over ikke at have grebet ind","Glæde over at være sluppet for ballade","Stolthed over at have passet sig selv"],"a":"Skyld over ikke at have grebet ind","r":"'Jeg skulle have sagt noget' er en anger, og 'sagde til mig selv' afslører, at undskyldningen var en bortforklaring."},
{"l":6750,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Skolefotografen skriver i brevet hjem: De allerfleste forældre vælger den store pakke, for skoletiden kommer aldrig igen.' Hvad vil sætningen få forældrene til at føle?","o":["At skolefotografen er billigere end andre","At de er særligt heldige med deres børns skole","At de svigter noget vigtigt, hvis de vælger mindre","At den lille pakke er bedre end den store"],"a":"At de svigter noget vigtigt, hvis de vælger mindre","r":"Henvisningen til 'de allerfleste' og tiden, der ikke kommer igen, spiller på forældres samvittighed. Det er et salgsgreb, ikke en oplysning."},
{"l":6770,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Vi vil have ro, vi vil have plads, vi vil have tid.' Hvilken virkning har gentagelsen i talen?","o":["Den skaber en truende og uhyggelig stemning","Den viser, at taleren er blevet forvirret","Den gør det svært for os at følge med","Den understreger budskabet og giver rytme"],"a":"Den understreger budskabet og giver rytme","r":"Når taleren gentager 'vi vil have', får sætningerne en stærk rytme, og budskabet bider sig fast."},
{"l":6787,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilken sætning indeholder en metafor?","o":["Hun er en sand løvinde på banen.","Hun kæmper som en løve i håndbold.","Hun spiller håndbold om tirsdagen.","Hun købte en bold med en løve på."],"a":"Hun er en sand løvinde på banen.","r":"Hun bliver kaldt en løvinde uden 'som' og ikke i bogstavelig forstand. Sætningen med 'som en løve' er en sammenligning."},
{"l":6800,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Skilt ved svømmehallen: Drenge og piger over 12 år skal gå i det store bassin.' Hvad er uklart ved skiltet?","o":["Om det store bassin faktisk er større end det lille","Om aldersgrænsen gælder for begge eller kun for pigerne","Om svømmehallen er åben for drenge og piger","Om børn over 12 år må gå i det store bassin"],"a":"Om aldersgrænsen gælder for begge eller kun for pigerne","r":"'Over 12 år' kan høre til hele udtrykket eller kun til 'piger'. Det er en klassisk tvetydighed i sætningsopbygningen."},
{"l":6821,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er 'krokodilletårer'?","o":["tårer af glæde over en stor sejr","tårer, der kommer af allergi","sorg, der er spillet og ikke ægte","sorg, der varer i mange år"],"a":"sorg, der er spillet og ikke ægte","r":"Ifølge en gammel fortælling græder krokodillen, mens den æder sit bytte. Ordet bruges om falsk medfølelse."},
{"l":6840,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning er rigtig om datoen for festen?","o":["Vi holder fest fredag den 13, juni.","Vi holder fest fredag den 13: juni.","Vi holder fest fredag, den 13 juni.","Vi holder fest fredag den 13. juni."],"a":"Vi holder fest fredag den 13. juni.","r":"Datoen er et ordenstal og skal have punktum efter tallet."},
{"l":6864,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find det rigtige ord: 'Der var ___ af billetterne i toget.'","o":["kontrol","kontroll","kontrool","kontrrol"],"a":"kontrol","r":"Ordet ender med ét l i grundformen. Først i bøjning som 'kontrollen' bliver der dobbelt-l."},
{"l":6882,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Når isalget stiger, stiger antallet af solskoldede også. Skal vi så forbyde is for at beskytte huden?' Hvad vil skribenten vise med sit spørgsmål?","o":["At is er skadeligt for huden, når man er ude i solen","At to ting kan stige samtidig, uden at den ene skaber den anden","At kommunen bør oplyse borgerne bedre om solens stråler","At isalget burde falde om sommeren af hensyn til sundheden"],"a":"At to ting kan stige samtidig, uden at den ene skaber den anden","r":"Forslaget er bevidst absurd. Begge tal stiger, fordi solen skinner, så is er ikke årsagen til solskoldning."},
{"l":6900,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Vi er mange, der mener, at den nye skolegård er en fejltagelse. Det hører jeg overalt.' Hvad mangler for at overbevise en kritisk læser?","o":["Hvem der har tegnet og bygget den nye skolegård","Om skribenten selv er imod den nye skolegård","Hvor mange 'vi' er, og hvad de bygger deres mening på","Hvad det er for en skole, der har fået gården"],"a":"Hvor mange 'vi' er, og hvad de bygger deres mening på","r":"'Mange' og 'overalt' er vage ord, der lyder af meget uden at sige noget præcist. Der er ingen tal eller begrundelser."},
{"l":6921,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"En regering giver 'amnesti' til en gruppe fanger. Hvad betyder det?","o":["de mister hukommelsen","de får længere straffe","de bliver flyttet til et andet land","de bliver fritaget for straf"],"a":"de bliver fritaget for straf","r":"Amnesti er en generel benådning. Forveksl det ikke med amnesi, som er tab af hukommelse."},
{"l":6943,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Der står 'bruttoløn' på Laras lønseddel. Hvad er det?","o":["lønnen, før skatten er trukket fra","lønnen, efter skatten er trukket fra","pengene, hun har sparet op i år","pengene, hun får i pension"],"a":"lønnen, før skatten er trukket fra","r":"Brutto betyder før fradrag. Det, man får udbetalt efter skat, hedder nettoløn."},
{"l":6960,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Den morgen vidste Laura ikke, at det var sidste gang, hun så sit barndomshjem.' Hvilken fortælleteknik bruges?","o":["tilbageblik","foregribelse","personifikation","sammenligning"],"a":"foregribelse","r":"Fortælleren røber noget, der først sker senere. Foregribelse skaber spænding, fordi vi ved mere end Laura."},
{"l":6981,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Sæt ind: 'Toget var en halv time ___ på grund af sne.'","o":["forsinked","forsingket","forsinket","forsinkt"],"a":"forsinket","r":"Tillægsformen ender på -et med t, selvom det lyder som d."},
{"l":7003,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"I hvilken sætning betyder 'da' det samme som 'fordi'?","o":["Da jeg var lille, boede vi i Aalborg.","Da klokken slog tolv, gik alle hjem.","Da vi kom hjem, var det blevet mørkt.","Da jeg er allergisk, spiser jeg ikke kagen."],"a":"Da jeg er allergisk, spiser jeg ikke kagen.","r":"'Da' kan angive både tid og årsag. I den rigtige sætning forklarer det, hvorfor jeg ikke spiser kagen."},
{"l":7020,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvad viser bindestregen i 'ind- og udgang'?","o":["At et ordled er sparet væk","At ordet deles ved linjeskift","At der er en lang pause her","At ordet er en forkortelse"],"a":"At et ordled er sparet væk","r":"Der står egentlig 'indgang og udgang'. Bindestregen viser, at 'gang' er sparet væk første gang."},
{"l":7041,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket dansk ord betyder det samme som 'metabolisme'?","o":["åndedræt","stofskifte","blodomløb","muskelkraft"],"a":"stofskifte","r":"Metabolisme er kroppens omsætning af næringsstoffer til energi og byggesten. Det danske ord er stofskifte."},
{"l":7063,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Det er kutyme at give hånd her.' Hvad betyder 'kutyme'?","o":["en streng lov","en sjov leg","skik og brug","en gammel fejl"],"a":"skik og brug","r":"Kutyme er et lidt gammeldags ord for en fast, almindelig praksis. Det er ikke en regel, man kan blive straffet for at bryde."},
{"l":7085,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad skal der stå? 'Forskerne har ___, at søvn styrker hukommelsen.'","o":["bevidst","bevisst","beviset","bevist"],"a":"bevist","r":"Ordet kommer af 'bevise', så der er intet d. 'Bevidst' betyder 'med vilje'."},
{"l":7104,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad kaldes det, en forfatter gerne vil sige til læseren med sin tekst?","o":["budskab","miljø","komposition","synsvinkel"],"a":"budskab","r":"Budskabet er tekstens hovedtanke til læseren. Man finder det ved at spørge, hvad teksten vil have os til at tænke over."},
{"l":7131,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hun gav et 'kryptisk' svar på spørgsmålet. Hvordan var svaret?","o":["kort og meget præcist","gådefuldt og svært at tyde","vredt og fornærmende","langt og meget kedeligt"],"a":"gådefuldt og svært at tyde","r":"Ordet kommer af det græske 'kryptos', som betyder skjult. En kryptisk besked skal man selv prøve at gennemskue."},
{"l":7152,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"En diskussion i klassen 'eskalerer'. Hvad sker der?","o":["den falder langsomt til ro","den går i stå uden resultat","den bliver gradvist voldsommere","den flytter til et andet lokale"],"a":"den bliver gradvist voldsommere","r":"At eskalere er at vokse trin for trin, som på en rulletrappe. Ordet bruges tit i avisen om konflikter, der trappes op."},
{"l":7172,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning bruger semikolon rigtigt mellem grupper, der selv indeholder kommaer?","o":["Gruppe 1 er Ida; Noah og Asta, gruppe 2 er Omar; Clara og Emil.","Gruppe 1; er Ida, Noah og Asta gruppe 2; er Omar, Clara og Emil.","Gruppe 1 er Ida, Noah; og Asta gruppe 2 er Omar, Clara; og Emil.","Gruppe 1 er Ida, Noah og Asta; gruppe 2 er Omar, Clara og Emil."],"a":"Gruppe 1 er Ida, Noah og Asta; gruppe 2 er Omar, Clara og Emil.","r":"Semikolon skiller de to større dele ad, mens kommaet ordner opremsningen inde i hver del."},
{"l":7194,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilke ord skal have stort i: 'Præsidenten bor i det hvide hus i Washington.'?","o":["de tre ord det, hvide og hus","kun det første ord, det","kun det sidste ord, hus","kun det midterste ord, hvide"],"a":"de tre ord det, hvide og hus","r":"Det Hvide Hus er et navn på en bestemt bygning, og alle tre ord i navnet får stort."},
{"l":7212,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket led er 'dem' i: 'Hun sendte dem en invitation til festen.'?","o":["direkte objekt","indirekte objekt","subjekt","prædikativ"],"a":"indirekte objekt","r":"Det, der sendes, er invitationen, og den er direkte objekt. 'Dem' er dem, der modtager den, og det er indirekte objekt."},
{"l":7234,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning har et omsagnsled og ikke et genstandsled?","o":["Min far ser kokken.","Min far kender kokken.","Min far er kok.","Min far hjælper kokken."],"a":"Min far er kok.","r":"Efter 'er' beskriver 'kok' grundleddet, og de to led er samme person. Ved de andre verber går handlingen ud over en anden."},
{"l":7253,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Sæt ind: 'En plante er ___ af lys og vand.'","o":["afhænging","avhængig","afhængi","afhængig"],"a":"afhængig","r":"Ordet hænger sammen med 'afhænge' og ender på -ig, ikke -ing."},
{"l":7272,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad krævede Georg Brandes af litteraturen i det moderne gennembrud?","o":["Den skulle sætte problemer under debat","Den skulle hylde fortidens guder og helte","Den skulle først og fremmest underholde børn","Den skulle holde sig fra alt det virkelige"],"a":"Den skulle sætte problemer under debat","r":"Brandes' berømte krav var, at litteraturen skulle sætte problemer under debat, f.eks. kvinders vilkår og troen."},
{"l":7300,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad er det latinske navn for ejestedord?","o":["demonstrative pronominer","possessive pronominer","interrogative pronominer","refleksive pronominer"],"a":"possessive pronominer","r":"Ejestedord hedder possessive pronominer. Demonstrative er påpegende, interrogative er spørgende, og refleksive er tilbagevisende."},
{"l":7314,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad kaldes den tid, handlingen i en tekst strækker sig over, f.eks. én sommer?","o":["nutid","kronik","fortalt tid","vendepunkt"],"a":"fortalt tid","r":"Den fortalte tid er tiden i historien, f.eks. en sommer eller et helt liv. En novelle har ofte kort fortalt tid."},
{"l":7333,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket stedord skal stå: 'Hun sad mellem Ali og ___ i bussen.'?","o":["jeg","min","vi","mig"],"a":"mig","r":"Efter forholdsord som 'mellem' står stedordet i afhængighedsform, altså 'mig', og det gælder også efter 'og'."},
{"l":7355,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad gør man, når man ud fra nogle få eksempler siger noget om alle?","o":["man generaliserer","man citerer","man refererer","man analyserer"],"a":"man generaliserer","r":"At generalisere er at gøre noget til en almen regel. Det bliver et svagt argument, hvis man kun bygger på få eksempler."},
{"l":7377,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket af disse verber har ingen form uden -s?","o":["læses","lykkes","bygges","vaskes"],"a":"lykkes","r":"'Lykkes' findes kun med -s. De andre er passive former af 'læse', 'bygge' og 'vaske'."},
{"l":7397,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Vi siger til unge, at de skal være sig selv. Så giver vi dem karakter for det.' Hvilken modstrid peger teksten på?","o":["Unge får for høje karakterer i forhold til indsatsen","Voksne stiller ingen krav til unge i dag","Opfordringen til frihed passer dårligt med bedømmelsen","Karakterer gives sjældent for det, unge kan"],"a":"Opfordringen til frihed passer dårligt med bedømmelsen","r":"Hvis man bliver bedømt, er man ikke fri til at være sig selv. De to korte sætninger sættes op mod hinanden for at vise det."},
{"l":7410,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning om maden står i passiv førnutid?","o":["Maden bliver spist.","Maden blev spist.","Maden var blevet spist.","Maden er blevet spist."],"a":"Maden er blevet spist.","r":"Førnutid dannes med 'er' i nutid. 'Bliver spist' er nutid, 'blev spist' er datid, og 'var blevet spist' er førdatid."},
{"l":7432,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad kendetegner en dystopi?","o":["En skræmmende fremtid, hvor samfundet er gået galt","En perfekt fremtid, hvor alle mennesker er lykkelige","En hyggelig fortid, hvor familien bor på landet","En sand beretning om et bestemt menneskes liv"],"a":"En skræmmende fremtid, hvor samfundet er gået galt","r":"Dystopien viser et samfund, der er kørt af sporet, og advarer os mod det. Den perfekte fremtid kaldes en utopi."},
{"l":7453,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad kendetegner en 'innovativ' virksomhed?","o":["den holder fast i gamle løsninger","den udvikler nye løsninger","den sælger varerne meget billigt","den er ejet af staten"],"a":"den udvikler nye løsninger","r":"Innovativ kommer af latin 'novus', som betyder ny. En innovativ virksomhed finder på noget nyt og får det til at virke i praksis."},
{"l":7474,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Kaptajn Noor så ned på Mars fra rumstationen. Skibets computer havde talt med hende hele natten.' Hvilken genre passer bedst?","o":["sagn","fabel","science fiction","folkevise"],"a":"science fiction","r":"Rumstationen og den talende computer peger på en fremtid formet af teknologi. Det er typisk for science fiction."},
{"l":7491,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad kendetegner 'konformitet' i en gruppe?","o":["at alle skiftes til at bestemme over de andre","at alle arbejder hver for sig med deres egne ting","at alle er født i samme år og bor i samme by","at alle tilpasser sig og gør som de andre"],"a":"at alle tilpasser sig og gør som de andre","r":"Konformitet betyder ensartethed. 'Kon' betyder sammen, og 'form' betyder form: Man former sig efter de andre for at passe ind."},
{"l":7506,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"To forslag rummer en 'fundamental' forskel. Hvad betyder det?","o":["en forskel i selve grundlaget","en forskel i nogle små detaljer","en forskel, der snart er væk","en forskel, der ses hvert år"],"a":"en forskel i selve grundlaget","r":"Fundamental kommer af 'fundament', altså det, noget er bygget på. En fundamental forskel går helt ned i grundlaget."},
{"l":7528,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Journalisten skal 'dokumentere' sin påstand. Hvad skal journalisten gøre?","o":["gentage den i flere artikler","vise med beviser, at den er rigtig","trække den tilbage igen","skrive den med større bogstaver"],"a":"vise med beviser, at den er rigtig","r":"At dokumentere er at bevise noget med kilder, tal eller papirer. Uden dokumentation står en påstand svagt."},
{"l":7546,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilket af ordene indleder en ledsætning, så der skal komma efter den, når den står først?","o":["men","og","mens","for"],"a":"mens","r":"'Mens' er et underordnende bindeord. 'Men', 'og' og 'for' binder sideordnede sætninger sammen."},
{"l":7568,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilket ord skal skrives med stort: 'Efter en lang gåtur gennem engene stod vi ved vadehavet.'?","o":["engene","gåtur","lang","vadehavet"],"a":"vadehavet","r":"Vadehavet er navnet på et bestemt havområde. 'Enge' er et almindeligt navneord."},
{"l":7590,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning skriver både tusindtal og decimaltal rigtigt?","o":["Der kom 1.250 tilskuere, og en billet kostede 37,50 kr.","Der kom 1,250 tilskuere, og en billet kostede 37.50 kr.","Der kom 1.250 tilskuere, og en billet kostede 37.50 kr.","Der kom 1,250 tilskuere, og en billet kostede 37,50 kr."],"a":"Der kom 1.250 tilskuere, og en billet kostede 37,50 kr.","r":"Tusinder adskilles med punktum, mens decimaler står efter et komma."},
{"l":7612,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Kun én af sætningerne bruger apostrof forkert. Hvilken?","o":["Der står mange pc'er på bordene i lokalet.","Der er mange bil'er på parkeringspladsen.","Vi har fire cd'er i skuffen under fjernsynet.","Jeg fik to sms'er fra min kusine i nat."],"a":"Der er mange bil'er på parkeringspladsen.","r":"Bil er ikke en forkortelse, så flertal skrives uden apostrof: biler."},
{"l":7631,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find det rigtige ord: 'Vi skal op ___ i morgen end i dag.'","o":["tilligere","tidlligere","tidligere","tidliger"],"a":"tidligere","r":"Ordet kommer af 'tidlig', så d'et skal med, og det stumme g bliver også stående."},
{"l":7656,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder 'autonom' i udtrykket 'en autonom robot'?","o":["fjernstyret","genopladelig","tohjulet","selvstyrende"],"a":"selvstyrende","r":"'Auto' betyder selv, og 'nom' kommer af græsk for lov. Noget autonomt sætter altså selv sine regler og styrer sig selv."},
{"l":7673,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg rigtigt: 'Jeg er ___ om, at du kan klare det.'","o":["overbevist","overbevidst","overbevisst","overbeviset"],"a":"overbevist","r":"Ordet kommer af 'overbevise' og har ikke noget d. 'Bevidst' med d er et helt andet ord."},
{"l":7696,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad fortæller 'syngende' i: 'Hun kom syngende ned ad vejen.'?","o":["hvornår hun kom","hvordan hun kom","hvorfra hun kom","hvem hun sang for"],"a":"hvordan hun kom","r":"Lang tillægsform efter 'komme' beskriver måden, man kommer på. Her sang hun, mens hun gik."},
{"l":7713,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad gør den, der 'giver igen med samme mønt'?","o":["betaler sin gæld tilbage med præcis det samme beløb","bytter en vare i den butik, hvor den er købt","svarer på samme måde, som han selv er blevet behandlet","deler sine penge lige med sine søskende"],"a":"svarer på samme måde, som han selv er blevet behandlet","r":"Udtrykket bruger penge som billede, men handler om opførsel: Har nogen været grov mod en, er man grov tilbage."},
{"l":7732,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilken tone har et 'polemisk' debatindlæg?","o":["en rolig og afvejet tone","en kort og faktuel tone","en stille og sørgmodig tone","en skarp og angribende tone"],"a":"en skarp og angribende tone","r":"Polemik kommer af det græske ord for krig. Et polemisk indlæg går til angreb på en modstanders synspunkter."},
{"l":7754,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"En indsamling viser et billede af en forladt hvalp for at vække medlidenhed. Hvilken appelform er der tale om?","o":["patos","logos","etos","topos"],"a":"patos","r":"Patos er appel til følelserne. Her skal billedet få modtageren til at føle medlidenhed og dermed give penge."},
{"l":7773,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Bedstefar fortalte den samme historie for tredje gang den aften. Vi grinede alle på de rigtige steder. Mor kiggede på mig over bordet og rystede næsten umærkeligt på hovedet, da jeg åbnede munden.' Hvad vil moren forhindre?","o":["At barnet begynder at fortælle en anden historie","At barnet afslører, at bedstefar gentager sig","At bedstefar opdager, at maden er ved at blive kold","At barnet griner højere end de andre ved bordet"],"a":"At barnet afslører, at bedstefar gentager sig","r":"De voksne spiller med for at skåne ham. Morens lille hovedrysten siger: Lad være med at påpege det."},
{"l":7795,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket bindebogstav er brugt i 'børnehave'?","o":["-s-","-n-","-e-","-r-"],"a":"-e-","r":"Ordet er sat sammen af 'børn' og 'have', og et -e- binder de to led sammen."},
{"l":7810,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Efter hvilket ord kræves der komma: 'Hun vil selvom det er svært prøve igen.'?","o":["det","prøve","igen","svært"],"a":"svært","r":"Ledsætningen 'selvom det er svært' er skudt ind i hovedsætningen og skal afsluttes med komma."},
{"l":7830,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Min nabo blev syg af at spise æg, så alle æg er farlige.' Hvilken argumentationsfejl er det?","o":["generalisering","falsk dilemma","personangreb","cirkelslutning"],"a":"generalisering","r":"Ét enkelt tilfælde bruges til at sige noget om alle æg. Det er en forhastet slutning fra én til alle."},
{"l":7852,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad kaldes en person, der ofrer sig for andres skyld uden at tænke på egen fordel?","o":["egoist","altruist","pessimist","solist"],"a":"altruist","r":"Altruisme kommer af latin 'alter', som betyder 'den anden'. Altruisten sætter andre før sig selv og er det modsatte af en egoist."},
{"l":7872,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Filmen starter stærkt, men midten trækker ud, og slutningen skuffer. Tre ud af seks stjerner.' Hvilken genre er det?","o":["reportage","fabel","anmeldelse","kronik"],"a":"anmeldelse","r":"Teksten vurderer et værk og giver det en karakter. Det er anmeldelsens opgave."},
{"l":7897,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Vi må hellere ___ et bord til på lørdag.'","o":["resservere","reserrvere","rezervere","reservere"],"a":"reservere","r":"Ordet har kun ét s og ét r i midten og står i navneform efter 'må'."},
{"l":7914,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilken journalistisk genre giver et nærbillede af et enkelt menneske gennem interview og beskrivelse?","o":["portræt","leder","notits","sonet"],"a":"portræt","r":"Et portræt tegner et billede af en person, både hvad personen har oplevet, og hvordan vedkommende er."},
{"l":7934,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Ridderen sprang op på sin 'ganger' og red af sted. Hvad er det?","o":["en vogn","en hest","en båd","en stige"],"a":"en hest","r":"'Ganger' er et ældre og poetisk ord for en ridehest. Det møder man i gamle romaner og folkeviser."},
{"l":7956,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Han var rig på penge, men fattig på venner.' Hvilket retorisk virkemiddel er der her?","o":["allitteration","personifikation","antitese","lydord"],"a":"antitese","r":"To modsætninger, rig og fattig, stilles direkte op mod hinanden. Det kaldes en antitese."},
{"l":7978,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Tre skoler har i et halvt år prøvet kortere skoledage. Eleverne svarer, at de er mere tilfredse. Lærerne oplever at nå mindre, men karaktererne er uændrede.' Hvilken overskrift dækker teksten mest præcist?","o":["Kortere skoledage giver dårligere karakterer","Elever og lærere lige begejstrede for de kortere skoledage","Forsøg viser: Lærerne når mere på kortere tid","Kortere skoledage: gladere elever, samme karakterer"],"a":"Kortere skoledage: gladere elever, samme karakterer","r":"Overskriften gengiver to resultater korrekt. De andre er i strid med teksten om karakterer eller lærernes oplevelse."},
{"l":7998,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvem er 'en ulv i fåreklæder'?","o":["en, der ser ufarlig ud, men er farlig","en, der ser farlig ud, men er rar","en, der er sulten hele dagen","en, der er klædt varmt på"],"a":"en, der ser ufarlig ud, men er farlig","r":"Udtrykket kommer fra Bibelen. Det bruges om en person, der skjuler onde hensigter bag et uskyldigt ydre."},
{"l":8012,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'I forbindelse med sagen om de forsvundne elevlister skriver kommunen: Der er desværre blevet begået fejl.' Hvad opnår kommunen med denne formulering?","o":["At forklare præcist, hvilke fejl der er begået","At undgå at sige, hvem der har lavet fejlene","At give eleverne skylden for de forsvundne lister","At afvise, at der overhovedet er sket fejl"],"a":"At undgå at sige, hvem der har lavet fejlene","r":"Passiv form skjuler den handlende. Der mangler en person, der siger: Det var os, der lavede fejlen."},
{"l":8033,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad kaldes en påstand, der fremsættes uden bevis?","o":["et citat","et referat","et postulat","et resultat"],"a":"et postulat","r":"Et postulat er en påstand, som bliver slået fast, men ikke bevist. I en debat kan man derfor sige: 'Det er bare et postulat.'"},
{"l":8052,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning er rigtig om tidspunktet for mødet?","o":["Mødet holdes tirsdag den 3. marts kl. 19,30.","Mødet holdes tirsdag den 3, marts kl. 19.30.","Mødet holdes tirsdag den 3. marts kl, 19.30.","Mødet holdes tirsdag den 3. marts kl. 19.30."],"a":"Mødet holdes tirsdag den 3. marts kl. 19.30.","r":"Ordenstallet og 'kl.' får punktum, og klokkeslæt skrives ikke med komma."},
{"l":8074,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Min morfar fangede engang en gedde så stor, at den trak båden tværs over Limfjorden, før den blev træt.' Hvilken fortælletype er det?","o":["skrøne","reportage","essay","sonet"],"a":"skrøne","r":"En skrøne er en stærkt overdrevet historie, der fortælles med et glimt i øjet, som om den var sand."},
{"l":8096,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvad betyder 'jf.', når det står i en faglig tekst?","o":["for eksempel","sammenlign med","det vil sige","og så videre"],"a":"sammenlign med","r":"'Jf.' står for 'jævnfør' og henviser læseren til noget, der kan sammenlignes."},
{"l":8115,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Elevrådets referat: Vi var 300, der gik fra skolen til rådhuset. Politiets oplysning: Omkring 100 deltog. Skolens hjemmeside: Mange elever deltog.' Hvad kan læseren konkludere med størst sikkerhed?","o":["Politiets tal må være det eneste rigtige tal","Elevrådet har med vilje oplyst et forkert tal","Der var en gruppe, som gik, men antallet er uklart","Der deltog præcis 200 elever, altså midt imellem tallene"],"a":"Der var en gruppe, som gik, men antallet er uklart","r":"Alle tre kilder er enige om, at noget skete, men ikke hvor mange. Man kan ikke uden mere viden vælge eller regne sig frem."},
{"l":8136,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning er en lettere udgave af: 'Der skal rettes henvendelse til kontoret.'?","o":["Kontoret skal kontakte dig.","Du har kontaktet kontoret.","Kontoret har rettet noget.","Du skal kontakte kontoret."],"a":"Du skal kontakte kontoret.","r":"Aktiv med et tydeligt 'du' og et almindeligt verbum gør sætningen lettere at forstå og bevarer betydningen."},
{"l":8160,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad siger man om en person, hvis man kalder ham en 'notorisk' sladderhank?","o":["at han er alment kendt for det","at han er meget ked af det","at han gør det i hemmelighed","at han netop er begyndt på det"],"a":"at han er alment kendt for det","r":"Notorisk betyder 'alment bekendt' og bruges næsten altid om noget negativt, for eksempel om en notorisk løgner."},
{"l":8183,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord ligger tættest på 'eminent' i udtrykket 'en eminent violinist'?","o":["forhenværende","fremragende","fremmed","forsigtig"],"a":"fremragende","r":"Eminent betyder fremragende. Ordet kommer af latin 'eminere', som betyder at rage op over andre."},
{"l":8200,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Lad mig gengive modpartens bedste argument, så retfærdigt jeg kan, før jeg siger, hvorfor jeg er uenig.' Hvad kan debattøren vinde ved den fremgangsmåde?","o":["Tid, fordi hun slipper for at komme med egne argumenter","Sympati fra modparten, så hun undgår at være uenig","Troværdighed, fordi hun viser, at hun har forstået sagen","Sejr i debatten, fordi modparten bliver dårligt fremstillet"],"a":"Troværdighed, fordi hun viser, at hun har forstået sagen","r":"Det er det modsatte af en stråmand. Når hun tager det stærkeste modargument alvorligt, får hendes egen kritik større vægt."},
{"l":8220,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvordan er en 'sirlig' håndskrift?","o":["stor og sjusket","hurtig og kantet","gammel og falmet","fin og omhyggelig"],"a":"fin og omhyggelig","r":"Sirlig betyder nydelig og omhyggelig med små detaljer. Ordet møder man tit i ældre litteratur."},
{"l":8243,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad sker der, når nogen 'åbner Pandoras æske'?","o":["de sætter noget i gang, der skaber mange problemer","de finder en skat, som er gemt i mange år","de opdager en hemmelighed om en nær ven","de får en gave, som de ikke har ønsket sig"],"a":"de sætter noget i gang, der skaber mange problemer","r":"I den græske myte åbnede Pandora en æske, og alt ondt slap ud i verden. Kun håbet blev tilbage."},
{"l":8263,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Kæmpepandaer spiser næsten kun bambus, som giver meget lidt energi. De bruger derfor det meste af dagen på at spise og bevæger sig kun lidt.' Hvad støtter teksten bedst?","o":["Pandaer er dovne af natur og hader at bevæge sig","Hvis bambus forsvinder, er pandaerne sårbare","Bambus giver mere energi end det meste andet","Pandaer kan nemt skifte over til at spise kød"],"a":"Hvis bambus forsvinder, er pandaerne sårbare","r":"Dyr, der næsten kun lever af én ting, er afhængige af den. Det er en slutning, teksten lægger op til, uden at sige det."},
{"l":8288,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"En avis omtaler et 'dubiøst' firma. Hvad antyder ordet?","o":["at firmaet er stort og meget kendt i hele landet","at firmaet er helt nyt og endnu ikke har kunder","at firmaet virker tvivlsomt og ikke helt til at stole på","at firmaet er ejet af to personer sammen"],"a":"at firmaet virker tvivlsomt og ikke helt til at stole på","r":"Dubiøs kommer af latin 'dubius', som betyder tvivlsom. Ordet antyder, at der er noget mistænkeligt."},
{"l":8309,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Da læreren havde rettet stilen, spurgte hun: Er du holdt op med at skrive af fra nettet?' Hvorfor er spørgsmålet svært for eleven at svare på?","o":["Eleven kan ikke vide, hvad læreren har rettet i stilen","Spørgsmålet handler om noget, eleven ikke må tale om","Læreren spørger om noget, eleven har svaret på før","Både ja og nej indrømmer, at eleven tidligere har skrevet af"],"a":"Både ja og nej indrømmer, at eleven tidligere har skrevet af","r":"Det ladede spørgsmål forudsætter, at eleven plejede at gøre det. Et ja og et nej bekræfter begge det forudsatte."},
{"l":8331,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvilket ord passer? 'Skolen sendte et brev ___ den kommende lejrtur.'","o":["vedrørende","vedrørene","vedrørrende","verørende"],"a":"vedrørende","r":"Ordet er dannet af 'vedrøre' med -ende, så d'et til sidst skal med, og det første d skal også med."},
{"l":8348,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder det, at to synspunkter er 'diametralt' modsatte?","o":["at de næsten ligner hinanden","at de er fuldstændig modsatte","at de begge er lige rigtige","at de kun er delvist forskellige"],"a":"at de er fuldstændig modsatte","r":"En diameter går tværs igennem cirklen fra side til side. Derfor bruges ordet om to ting, der står så langt fra hinanden som muligt."},
{"l":8374,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilken digter skrev 'Jens Vejmand', der skildrer en fattig arbejders hårde liv?","o":["Adam Oehlenschläger","Tove Ditlevsen","Jeppe Aakjær","Karen Blixen"],"a":"Jeppe Aakjær","r":"Jeppe Aakjær skrev ofte om livet i Jylland og om dem, der havde det hårdest. Sangen er stadig velkendt."},
{"l":8400,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Forskere taler om et 'paradigmeskift'. Hvad er det, der skifter?","o":["den person, der står i spidsen for et stort institut","den måde, man skriver henvisninger på i en rapport","det sprog, som man publicerer sine resultater på","hele den grundlæggende måde at tænke på i et fag"],"a":"hele den grundlæggende måde at tænke på i et fag","r":"Et paradigme er en grundforståelse, der styrer et fag. Det var et paradigmeskift, da man forstod, at Jorden kredser om Solen."},
{"l":8415,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg det sammensatte ord: 'Alle i bilen skal bruge en ___.'","o":["sikkerhedssele","sikkerhedsele","sikkerhedsselle","sikkerhedesele"],"a":"sikkerhedssele","r":"Her mødes fuge-s'et og s'et i 'sele', så der skal to s'er midt i ordet."},
{"l":8438,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Firmaet er bekymret for sit 'renommé'. Hvad er det?","o":["dets næste flytning","dets gode navn","dets gamle lokaler","dets daglige drift"],"a":"dets gode navn","r":"Renommé betyder omdømme: det, andre mener om en. Ordet kommer fra fransk og er i familie med 'nom', som betyder navn."},
{"l":8457,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Skolelederen indrømmede, at eleverne havde fået for lidt undervisning.' Hvad antyder ordet 'indrømmede', som ordet 'sagde' ikke gør?","o":["At hun er meget stolt af det, hun fortæller om skolen","At hun ikke har forstået, hvad journalisten spurgte hende om","At det er noget negativt, hun helst ville undgå at sige","At hun fortalte det til eleverne, længe før det skete"],"a":"At det er noget negativt, hun helst ville undgå at sige","r":"Journalistens valg af udsagnsord farver budskabet. 'Indrømmede' antyder pres og en fejl, som 'sagde' ikke gør."},
{"l":8480,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Ingen talte om den tomme plads ved vinduet. Læreren skubbede stolen ind under bordet hver morgen, og hver morgen stod den trukket ud igen.' Hvad antyder teksten?","o":["At læreren har lavet en fejl i klassens faste bordplan","At stolen står for tæt på vinduet og skal flyttes","At en ny elev allerede er begyndt at sidde på pladsen","At nogen i klassen ikke vil lade den fraværende blive glemt"],"a":"At nogen i klassen ikke vil lade den fraværende blive glemt","r":"Nogen gør det hver dag uden ord. Den trukne stol holder pladsen åben og er et tavst tegn på savn."},
{"l":8499,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken form passer: 'Det var nogle ___ dage på Læsø.'?","o":["dejlige","dejlig","dejligt","dejliges"],"a":"dejlige","r":"Tillægsordet retter sig efter 'dage', som står i flertal. 'Det' i begyndelsen af sætningen ændrer ikke på det."},
{"l":8521,"g":8,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket led er 'at læse' i: 'Hun elsker at læse.'?","o":["grundled","genstandsled","hensynsled","omsagnsled"],"a":"genstandsled","r":"Spørg: Hvad elsker hun? Svaret er 'at læse'. Et verbum i navneform kan altså være genstandsled."},
{"l":8543,"g":8,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder det, at et menneske er blevet 'vejet og fundet for let'?","o":["at personen har tabt sig meget i vægt","at personen ikke tager noget særlig alvorligt","at personen ikke lever op til kravene","at personen er nem at løfte og flytte"],"a":"at personen ikke lever op til kravene","r":"Udtrykket stammer fra Daniels Bog i Bibelen. Det bruges om nogen, der er blevet bedømt og ikke har vist sig god nok."},
{"l":8568,"g":8,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad gør den, der 'vasker sine hænder' i en sag?","o":["retter op på sine fejl","tilstår sin skyld","arbejder hårdt","fralægger sig ansvaret"],"a":"fralægger sig ansvaret","r":"Udtrykket stammer fra Bibelen, hvor Pilatus vasker sine hænder for at vise, at han ikke vil have ansvaret. I dag bruges det om at frasige sig ansvar."},
{"l":8596,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvilken roman udgav Klaus Rifbjerg i 1958?","o":["Den kroniske uskyld","Det forsømte forår","Hærværk","Niels Lyhne"],"a":"Den kroniske uskyld","r":"'Den kroniske uskyld' handler om ungdom og blev en moderne klassiker. Rifbjerg var en central skikkelse i 1960'ernes modernisme."},
{"l":8618,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvilken forfatter skrev romanen 'Bipersonerne' fra 1956?","o":["Villy Sørensen","Peter Seeberg","Klaus Rifbjerg","Leif Panduro"],"a":"Peter Seeberg","r":"Peter Seeberg debuterede med 'Bipersonerne', en modernistisk roman om menneskers tomhed og tilfældighed."},
{"l":8640,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvilken digter skrev systemdigtet 'alfabet' fra 1981, der bygger på fibonaccirækken?","o":["Tove Ditlevsen","Klaus Rifbjerg","Inger Christensen","Benny Andersen"],"a":"Inger Christensen","r":"Inger Christensens 'alfabet' er bygget efter faste regler: alfabetet og fibonaccital bestemmer digtets længde."},
{"l":8662,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs digtet: 'regn regn regn / regn regn / regn / r' Hvad viser digtets form bedst?","o":["At regnen bliver stærkere og stærkere","At det regner lige meget hele tiden","At regnen er blevet til sne og is","At regnen langsomt holder op"],"a":"At regnen langsomt holder op","r":"Linjerne bliver kortere og kortere, og det sidste ord er næsten væk. Formen viser selv, hvad der sker."},
{"l":8684,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad ville digterne i symbolismen omkring 1890?","o":["Antyde en skjult virkelighed gennem stemninger","Skildre fattigdom nøgternt og med fakta","Skrive komedier, der kunne opdrage folket","Bruge sprog fra reklamer og aviser i digte"],"a":"Antyde en skjult virkelighed gennem stemninger","r":"Symbolisterne vendte sig mod naturalismen og ville antyde det, der ligger bag det synlige."},
{"l":8706,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad kendetegner en kollektivroman?","o":["Den er skrevet af mange forfattere sammen","Den har en hel gruppe som hovedperson","Den handler kun om bønder i 1700-tallet","Den består af breve mellem to venner"],"a":"Den har en hel gruppe som hovedperson","r":"I en kollektivroman er det gruppen eller lokalsamfundet, der er i centrum, ikke én enkelt person."},
{"l":8725,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad kaldes det, når en leder giver gode stillinger til sin egen familie?","o":["patriotisme","pacifisme","nepotisme","nomadisme"],"a":"nepotisme","r":"Latin 'nepos' betyder nevø. Før i tiden gav magthavere ofte vigtige poster til deres nevøer."},
{"l":8745,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad er rigtigt? 'En ___ er en kort fortælling med få personer.'","o":["novele","novvelle","novælle","novelle"],"a":"novelle","r":"Ordet har ét v og dobbelt-l."},
{"l":8762,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord passer: 'Holdet var i ren ___ efter sejren: Alle jublede og dansede i omklædningsrummet.'","o":["eufori","apati","letargi","melankoli"],"a":"eufori","r":"Eufori er en stærk, opløftet glæde. Forleddet eu- betyder godt, og de tre andre ord beskriver tungsind eller sløvhed."},
{"l":8788,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilken sætning er rigtig, når et enkelt ord er sat i anførselstegn?","o":["Hun kaldte det et, »mesterværk« og alle grinede.","Hun kaldte det et »mesterværk«, og alle grinede.","Hun kaldte det »et mesterværk og« alle grinede.","Hun kaldte det et »mesterværk« og, alle grinede."],"a":"Hun kaldte det et »mesterværk«, og alle grinede.","r":"Anførselstegnene står om ét ord, og kommaet mellem de to hovedsætninger står foran 'og'."},
{"l":8806,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket af disse ord har dansk fået fra grønlandsk?","o":["sofa","pizza","kajak","sauna"],"a":"kajak","r":"'Kajak' kommer af det grønlandske 'qajaq'. 'Sofa' kommer fra arabisk, 'pizza' fra italiensk og 'sauna' fra finsk."},
{"l":8828,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket led står i forfeltet i: 'Den film har jeg set tre gange.'","o":["grundled","udsagnsled","sætningsadverbial","genstandsled"],"a":"genstandsled","r":"'Den film' er det, der bliver set, altså genstandsleddet. Det er flyttet frem i forfeltet, så grundleddet 'jeg' står efter det bøjede udsagnsord."},
{"l":8850,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Ordene 'kat' og 'hat' adskiller sig kun ved den første lyd og betyder noget forskelligt. Hvad kan man slutte af det?","o":["at k og h er to forskellige fonemer","at k og h er det samme fonem","at ordene har samme rodmorfem","at ordene er lånt fra samme sprog"],"a":"at k og h er to forskellige fonemer","r":"Et fonem er en lyd, der kan skelne ord fra hinanden. Sådan et ordpar kaldes et minimalpar, og det viser, at de to lyde er forskellige fonemer."},
{"l":8871,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad er rygdækning i Toulmins argumentmodel?","o":["En beskyttelse af afsenderens privatliv","Yderligere støtte til, at hjemlen holder","Den sidste sætning, der opsummerer alt","Et ord, der viser, hvor sikker man er"],"a":"Yderligere støtte til, at hjemlen holder","r":"Rygdækning bakker hjemlen op, hvis nogen tvivler på den. Ordet, der viser sikkerhed, kaldes styrkemarkør."},
{"l":8892,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvordan trækker man 'sommerferie' og 'sommerhus' sammen?","o":["sommerferie- og hus","sommerferie og hus","sommerferie og -hus","sommerferie og- hus"],"a":"sommerferie og -hus","r":"Når det første led er sparet væk i det andet ord, står bindestregen foran det, der er tilbage."},
{"l":8910,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Vælg stavemåden: 'Stjernehimlen er et ___ syn.'","o":["facinerende","fasinerende","fascinerene","fascinerende"],"a":"fascinerende","r":"Ordet skrives med sc, og -ende har d til sidst."},
{"l":8927,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ordpar adskilles i udtalen kun af stød?","o":["man – mand","bil – pil","sol – sal","hus – mus"],"a":"man – mand","r":"D er stumt i 'mand', så begge ord har de samme lyde, men 'mand' har stød. I de andre par er det en konsonant eller en vokal, der adskiller ordene."},
{"l":8949,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken form passer: 'Et af husene i vores gade er meget ___.'","o":["gammel","gammelt","gamle","gamles"],"a":"gammelt","r":"Grundleddet er 'Et', ikke 'husene'. Tillægsordet skal derfor stå i ental og intetkøn, selvom flertalsordet står tættest på."},
{"l":8970,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilken sætning er rigtig, når replikken består af to sætninger?","o":["Mor sagde: »Luk døren.« Det trækker.«","Mor sagde: »Luk« døren. Det trækker.«","Mor sagde: »Luk døren. Det trækker.«","»Mor sagde: Luk døren. Det trækker.«"],"a":"Mor sagde: »Luk døren. Det trækker.«","r":"Anførselstegnene åbner før første sætning og lukker efter sidste. Replikkens punktummer står inden for dem."},
{"l":8993,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvad er rodmorfemet i 'usynlighed'?","o":["u-","-lig","-hed","syn"],"a":"syn","r":"Roden er det morfem, der bærer ordets grundbetydning. Forstavelsen 'u-' og endelserne '-lig' og '-hed' er bundne morfemer, der er sat på roden."},
{"l":9014,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Modet, tålmodigheden og håbet bar os igennem.' Hvad kaldes det, når man opremser tre led for at give rytme og slagkraft?","o":["trekløver","oxymoron","eufemisme","metonymi"],"a":"trekløver","r":"Tre led hænger godt sammen i øret og virker afsluttede. Derfor bruger talere ofte trekløveret."},
{"l":9032,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hanne 'kautionerer' for sin søns lån. Hvad betyder det?","o":["Hun advarer ham mod at låne penge","Hun hæfter for lånet, hvis han ikke betaler","Hun har selv lånt pengene af ham","Hun sørger for, at han får en lavere rente i banken"],"a":"Hun hæfter for lånet, hvis han ikke betaler","r":"Den, der stiller kaution, lover at betale, hvis låntageren ikke kan. Det er derfor en stor forpligtelse."},
{"l":9052,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Søjlediagrammet viser antal elever i lektiehjælp: 100 i 2021, 120 i 2022 og 125 i 2023. Pjecen skriver: Stigningen fortsætter.' Hvad skjuler formuleringen?","o":["At antallet af elever er faldet igen i det sidste år","At tallene for 2021 og 2022 er byttet om i diagrammet","At stigningen er blevet langt mindre fra år til år","At der i 2023 kom flere til end i årene før"],"a":"At stigningen er blevet langt mindre fra år til år","r":"Fra 20 flere til 5 flere: Udsagnet er sandt, men læseren får indtryk af fremdrift, skønt udviklingen er ved at stoppe."},
{"l":9074,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Efter hvilket ord skal der stå komma: 'Hvor meget det koster afhænger af hvor mange der kommer.'?","o":["meget","afhænger","mange","koster"],"a":"koster","r":"'Hvor meget det koster' er en ledsætning, der er grundled. Den slutter efter 'koster'."},
{"l":9092,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad gør man, når man 'sætter kikkerten for det blinde øje'?","o":["lader, som om man ikke ser noget ubehageligt","undersøger en sag meget nøje og grundigt fra alle sider","ser langt ud i fremtiden med stort håb","kigger på noget, man ikke må se"],"a":"lader, som om man ikke ser noget ubehageligt","r":"Admiral Nelson gjorde det ifølge historien under Slaget på Reden i 1801 for ikke at se et signal om at trække sig."},
{"l":9113,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Eleverne blev talt op, sorteret og sat på plads i rækker.' Hvad kaldes det, at mennesker her beskrives som ting?","o":["personifikation","tingsliggørelse","synæstesi","apostrofe"],"a":"tingsliggørelse","r":"Tingsliggørelse er det modsatte af personifikation. Mennesker omtales, som om de var varer eller genstande."},
{"l":9130,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad gør man, når man 'går i brechen for' en kollega?","o":["taler bag vedkommendes ryg","overtager vedkommendes stilling","tager kampen op for vedkommende","undgår at tale med vedkommende"],"a":"tager kampen op for vedkommende","r":"En breche er et hul i en fæstningsmur. Den, der stiller sig i hullet, forsvarer dem, der er bagved."},
{"l":9152,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Forfatteren 'tager til genmæle' i avisen. Hvad gør hun?","o":["trækker sin artikel tilbage fra avisen","roser en anden forfatters nye bog","fortæller om sin barndom på landet","svarer igen på den kritik, hun har fået"],"a":"svarer igen på den kritik, hun har fået","r":"Et genmæle er et svar. Udtrykket bruges især, når nogen forsvarer sig mod kritik eller et angreb."},
{"l":9175,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"En gruppe unge kunstnere udsendte et 'manifest'. Hvad er det?","o":["en offentlig erklæring om mål og principper","en privat dagbog om det daglige arbejde","en liste over tidligere medlemmer af gruppen","en ordbog over særlige fagudtryk i kunsten"],"a":"en offentlig erklæring om mål og principper","r":"Latin 'manifestus' betyder tydelig. I et manifest gør en gruppe det klart, hvad den vil og står for."},
{"l":9195,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Bjergene omkranser et højt ___.'","o":["platou","plateau","plattå","platå"],"a":"plateau","r":"Ordet kommer fra fransk og ender på -eau, selvom det lyder som o."},
{"l":9212,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Ordene 'sparsommelig' og 'nærig' kan beskrive samme adfærd, men de vækker forskellige følelser. Hvad kaldes sådan en bibetydning?","o":["denotation","deklination","konnotation","definition"],"a":"konnotation","r":"Konnotationen er den værdi, et ord bærer med sig, her positiv og negativ. Denotationen er ordets rene grundbetydning."},
{"l":9234,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvorfor kaldes Herman Bangs skrivemåde ofte scenisk?","o":["Fordi han kun skrev skuespil til teatret","Fordi hans romaner altid foregår på et teater","Fordi han gav hver scene et nummer i teksten","Fordi læseren ser personerne handle og tale"],"a":"Fordi læseren ser personerne handle og tale","r":"Bang lader personerne vise sig gennem replikker og små bevægelser, som på en scene, og forklarer ikke meget selv."},
{"l":9255,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Hun vandt løbet med en ___ sejr.'","o":["suveræn","suveren","suverræn","suværæn"],"a":"suveræn","r":"Ordet ender på -æn, og det har ét r og e i anden stavelse."},
{"l":9272,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad kendetegner en 'servil' medarbejder?","o":["dygtighed til at servere i kantinen","krybende underdanighed over for chefen","en vane med at modsige chefen","lyst til at arbejde helt alene"],"a":"krybende underdanighed over for chefen","r":"Servil kommer af latin 'servus', slave. Ordet har intet med servering at gøre, men beskriver slesk lydighed."},
{"l":9295,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad er en 'renegat'?","o":["en, der trofast holder ved sin sag hele livet","en, der genopbygger gamle og forfaldne huse","en, der svigter sin sag og går over til modparten","en, der er vendt hjem efter mange år i udlandet"],"a":"en, der svigter sin sag og går over til modparten","r":"Latin 'renegare' betyder at fornægte. Ordet bruges om en frafalden og har en meget negativ klang."},
{"l":9315,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad står der rigtigt? 'I sit ___ bestemte den gamle skibsreder, at huset skulle gå til byen.'","o":["testamænte","tesstamente","testemente","testamente"],"a":"testamente","r":"Ordet har ét s og staves te-sta-men-te."},
{"l":9334,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Talordet 'halvtreds' er en rest af en gammel måde at tælle på. Hvilket regnestykke gemmer sig i ordet?","o":["to og en halv gange tyve","tre og en halv gange tyve","fem gange ti","tres minus ti"],"a":"to og en halv gange tyve","r":"'Halvtreds' er forkortet af 'halvtredsindstyve'. 'Halvtredje' betyder to og en halv, og 'sinde' betyder gange, så der tælles i tyvere."},
{"l":9356,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket af disse sammensatte ord har et fugeelement mellem leddene?","o":["fodbold","arbejdsdag","solskin","bogreol"],"a":"arbejdsdag","r":"Et fugeelement er en lille lyd, der binder leddene sammen. I 'arbejdsdag' er det -s-, mens de andre ord er sat direkte sammen."},
{"l":9377,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilken sproglig figur er udtrykket 'en larmende tavshed'?","o":["pleonasme","onomatopoietikon","oxymoron","akronym"],"a":"oxymoron","r":"Et oxymoron sætter to modsatte ord sammen. Ordet er selv dannet af græsk for 'skarp' og 'dum'."},
{"l":9399,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad kaldes perioden i første halvdel af 1800-tallet, hvor dansk kunst og litteratur blomstrede?","o":["oplysningstiden","barokken","renæssancen","guldalderen"],"a":"guldalderen","r":"Guldalderen rummer navne som H.C. Andersen, Søren Kierkegaard og Thorvaldsen, trods landets økonomiske krise."},
{"l":9422,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"I et skuespil om vikingerne kigger en høvding på sit armbåndsur. Hvad kaldes sådan en fejl i tiden?","o":["anakronisme","anekdote","antiklimaks","anafor"],"a":"anakronisme","r":"Ana- betyder her tilbage, og krono- betyder tid. En anakronisme placerer noget på et tidspunkt, hvor det ikke kan høre hjemme."},
{"l":9444,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken sætning gengiver spørgsmålet 'Har du spist?' som indirekte tale, når far spørger Noah?","o":["Far spurgte Noah, at han havde spist.","Far spurgte Noah, om han havde spist.","Far spurgte Noah, hvis han havde spist.","Far spurgte Noah, da han havde spist."],"a":"Far spurgte Noah, om han havde spist.","r":"Et ja/nej-spørgsmål bliver til en ledsætning med 'om'. Samtidig bliver 'du' til 'han', og tiden rykker fra 'har' til 'havde'."},
{"l":9465,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Find den rigtige stavemåde: 'Da manuskriptet forsvandt, måtte skuespilleren ___.'","o":["improvicere","inprovisere","improvisere","improvissere"],"a":"improvisere","r":"Ordet begynder med im-, fordi der kommer et p efter, og s-lyden er ét s."},
{"l":9482,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord passer: 'Den ___ direktør tænkte kun på overskuddet og var ligeglad med, om nogen blev ramt.'","o":["naive","idealistiske","hensynsfulde","kyniske"],"a":"kyniske","r":"Kynisk betyder følelseskold og uden hensyn til moral. En idealist ville omvendt lade høje idealer styre sine handlinger."},
{"l":9504,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'På rejsen tog vi billeder af alt. Vi har 4.000 af dem. Jeg kan ikke huske, hvordan der lugtede.' Hvad peger uddraget på?","o":["At dokumentationen kan komme til at erstatte oplevelsen","At 4.000 billeder er for få til at huske en lang rejse","At fortælleren har mistet sin lugtesans under rejsen","At fotos af høj kvalitet kræver et meget godt kamera"],"a":"At dokumentationen kan komme til at erstatte oplevelsen","r":"Billederne gemmer kun det synlige. Tabet af lugten viser, at de kan have stået i vejen for det, de skulle bevare."},
{"l":9525,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Du skal vise ___, når du henter pakken.'","o":["legimation","legitimation","legitimasjon","legitimmation"],"a":"legitimation","r":"Ordet har stavelserne le-gi-ti-ma-tion. Mange glemmer stavelsen -ti-."},
{"l":9542,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Landmændene modtager 'subsidier'. Hvad er det?","o":["særlige afgifter til staten hvert år","lån fra udenlandske banker","økonomisk støtte fra det offentlige","fradrag for gamle maskiner"],"a":"økonomisk støtte fra det offentlige","r":"Latin 'subsidium' betyder hjælp. Subsidier er tilskud, der holder prisen nede eller støtter et erhverv."},
{"l":9565,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilken stilfigur bruger taleren: 'Vi vil have ro. Vi vil have tid. Vi vil have plads.'?","o":["litote","pastiche","sentens","anafor"],"a":"anafor","r":"En anafor gentager samme ord i begyndelsen af flere sætninger. Gentagelsen giver talen rytme og kraft."},
{"l":9587,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Filosoffer taler om viden 'a priori'. Hvad er det?","o":["viden, der gælder uafhængigt af erfaring","viden, der stammer fra mange forsøg","viden, som kun eksperter har adgang til","viden, der er gået i arv i slægten"],"a":"viden, der gælder uafhængigt af erfaring","r":"A priori betyder 'ud fra det forudgående'. At 2 + 2 = 4, kan man for eksempel indse uden at undersøge verden."},
{"l":9608,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvilken sætning udtrykker størst sikkerhed?","o":["Det må formodes at virke.","Det virker utvivlsomt.","Det burde virke.","Det virker formentlig."],"a":"Det virker utvivlsomt.","r":"'Utvivlsomt' betyder, at der ingen tvivl er. 'Må formodes', 'burde' og 'formentlig' viser alle, at afsenderen tager forbehold."},
{"l":9630,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"En avis skriver 'en larmende flok unge', en anden 'en gruppe unge'. Hvad viser ordvalget i den første avis?","o":["Det viser, hvor mange unge der præcis var","Det viser, at avisen er saglig og neutral","Det viser en negativ vurdering af de unge","Det viser, at de unge har givet et interview"],"a":"Det viser en negativ vurdering af de unge","r":"Ordene 'larmende' og 'flok' er værdiladede. Ordvalget farver, hvordan læseren ser de unge."},
{"l":9647,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Anmelderen kalder skuespillerens præstation en 'tour de force'. Hvad er det?","o":["en stor og ærgerlig skuffelse","en lang rejse gennem Frankrig","en ren gentagelse af det gamle","en imponerende kraftpræstation"],"a":"en imponerende kraftpræstation","r":"Udtrykket er fransk og betyder 'kraftkunststykke'. Det har altså intet med cykelløb at gøre."},
{"l":9671,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Vi lærte hurtigt, hvilke spørgsmål der ikke skulle stilles. Hvor far var om tirsdagen. Hvorfor kuverterne lå under avisen. Hvem der ringede, når mor gik ud i gangen med telefonen.' Hvad viser opremsningen?","o":["At børnene har lært at undgå det, der truer familiens ro","At børnene er blevet nysgerrige efter fars arbejde","At børnene selv står bag det, der foregår om tirsdagen","At børnene ikke har nogen interesse i forældrenes liv"],"a":"At børnene har lært at undgå det, der truer familiens ro","r":"De ufuldstændige sætninger viser, at børnene ser meget, men ikke siger noget. Deres tavshed er tillært og beskyttende."},
{"l":9690,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad skal der stå? 'Larmen fra byggepladsen var ___.'","o":["uuholdelig","uudholdelig","uudhollelig","uudholdlig"],"a":"uudholdelig","r":"Ordet består af 'u' og 'udholdelig', og der er to u'er og to d'er."},
{"l":9708,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvorfor bruger faglige tekster ofte nominaliseringer?","o":["De gør teksten lettere for børn.","De gør sproget mere personligt.","De kan samle meget indhold i få ord.","De kan erstatte alle fagord."],"a":"De kan samle meget indhold i få ord.","r":"En nominalisering pakker en hel handling ind i ét navneord, som derefter kan bruges videre i teksten. Prisen er, at teksten kan blive tungere at læse."},
{"l":9730,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvorfor kan man skrive 'Pandekager er godt', selvom 'pandekager' står i flertal?","o":["'godt' er et navneord i intetkøn her.","'pandekager' er et ord i intetkøn ental.","'godt' bøjes aldrig efter navneordet.","'godt' henviser til det at spise pandekager."],"a":"'godt' henviser til det at spise pandekager.","r":"Tillægsordet kongruerer her med betydningen, ikke med formen. Det er det at spise pandekager, der er godt, og sådan en handling får intetkønsform."},
{"l":9751,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvordan adskilte 1960'ernes modernister som Klaus Rifbjerg sig fra Heretica-kredsen?","o":["De vendte sig mod hverdag, storby og massekultur","De vendte sig mod bondelivet og folkeviserne","De ville genoplive de nordiske guder i digte","De skrev kun rimede sonetter om naturen"],"a":"De vendte sig mod hverdag, storby og massekultur","r":"Heretica søgte åndelige værdier efter krigen. 1960'ernes modernister tog fat på det moderne hverdagsliv og forbrugssamfundet."},
{"l":9774,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Se på ledsætningen 'fordi Liva ikke kom'. Hvilken rækkefølge har leddene efter bindeordet?","o":["bøjet udsagnsord, grundled, sætningsadverbial","grundled, sætningsadverbial, bøjet udsagnsord","sætningsadverbial, grundled, bøjet udsagnsord","grundled, bøjet udsagnsord, sætningsadverbial"],"a":"grundled, sætningsadverbial, bøjet udsagnsord","r":"I ledsætningens skema kommer grundleddet først, så sætningsadverbialet og derefter det bøjede udsagnsord. Hovedsætningen ville have 'kom' foran 'ikke'."},
{"l":9795,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad står der rigtigt? 'De to forskere havde en lang ___ via breve.'","o":["korespondance","korrespondanse","korrespondance","korrespondence"],"a":"korrespondance","r":"Ordet har dobbelt-r og ender på -ance på dansk, ikke -ence som på engelsk."},
{"l":9812,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilken slags forklaring er det at sige: 'Øjet findes, for at vi kan se'?","o":["kronologisk","etymologisk","fænomenologisk","teleologisk"],"a":"teleologisk","r":"Græsk 'telos' betyder mål eller formål. En teleologisk forklaring ser på, hvad noget er til for, og ikke hvad der har forårsaget det."},
{"l":9835,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad hævder en tilhænger af 'solipsisme'?","o":["at kun ens egen bevidsthed med sikkerhed findes","at alle mennesker er forbundet med hinanden","at mennesket først og fremmest bør leve alene","at solen er midtpunktet i vores univers"],"a":"at kun ens egen bevidsthed med sikkerhed findes","r":"Latin 'solus ipse' betyder 'alene sig selv'. Solipsisten mener, at alt andet kan være noget, ens egen bevidsthed bilder sig ind."},
{"l":9854,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilken skrivemåde er rigtig, når hver billet koster 50 kr.?","o":["3 billetter á 50 kr.","3 billetter à 50 kr.","3 billetter a' 50 kr.","3 billetter à: 50 kr."],"a":"3 billetter à 50 kr.","r":"Det lille ord à betyder 'til en pris af' og skrives med en accent, der hælder mod venstre."},
{"l":9880,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvad viser accenten i: 'Vi har kun én cykel.'?","o":["At ordet er et stedord i flertal","At der mangler et bogstav i ordet","At ordet er et talord og skal betones","At ordet er et fremmedord fra fransk"],"a":"At ordet er et talord og skal betones","r":"Accenten viser, at der menes tallet 1, og at ordet skal have tryk."},
{"l":9897,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Firmaet planter et træ for hver 1.000. bil, det sælger. Det står på forsiden af alle brochurer. Bilerne står nævnt med småt: 500.000 om året.' Hvad antyder sammenstillingen?","o":["At firmaet planter mange flere træer, end det har oplyst i sine brochurer","At brochuren er trykt på papir fra de træer, som firmaet selv har plantet","At bilerne er blevet mindre forurenende, siden firmaet plantede træerne","At den grønne indsats er lille og fremhæves mest for billedets skyld"],"a":"At den grønne indsats er lille og fremhæves mest for billedets skyld","r":"500 træer mod en halv million biler. Forsiden og det lille skrift afslører prioriteringen."},
{"l":9917,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"'Der er tyve sultne munde at mætte', siger kokken og mener tyve gæster. Hvilken figur bruger hun?","o":["synekdoke","hyperbel","antitese","eufemisme"],"a":"synekdoke","r":"Synekdoke er en figur, hvor en del står for helheden. Her står munden for hele personen."},
{"l":9938,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'En skole uden bibliotek er som en krop uden hjerte, så vi må bevare biblioteket.' Hvilken argumenttype er det?","o":["cirkelslutning","analogi","personangreb","stråmand"],"a":"analogi","r":"En analogi overfører noget fra et område til et andet. Den kan være stærk, men man må spørge, om de to ting ligner hinanden nok."},
{"l":9960,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad er rigtigt? 'De mange regler og formularer gjorde sagen til et stort ___.'","o":["burokrati","bureukrati","bureaukrati","byråkrati"],"a":"bureaukrati","r":"Ordet består af det franske 'bureau' og det græske 'kratos' for magt, så -eau bevares."},
{"l":9980,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Skolens vision er, at alle elever skal lykkes. Vi spurgte skolelederen, hvad der sker, hvis en elev ikke lykkes. Hun svarede, at det ikke er en del af visionen.' Hvad røber svaret ufrivilligt?","o":["At skolelederen har tænkt grundigt over, hvad skolen gør for hver elev","At alle elever på skolen faktisk er lykkedes med skolens hjælp","At journalisten har misforstået, hvad en vision betyder i skolen","At visionen ikke rummer et svar på de elever, der har mest brug for det"],"a":"At visionen ikke rummer et svar på de elever, der har mest brug for det","r":"Svaret er ment som et forsvar, men viser, at de elever, der ikke lykkes, ikke er tænkt med. Ufrivillig komik afslører en svaghed."}
]$$::jsonb) AS e
JOIN (VALUES
  ('s', 'stavning', 'recall', 'factual', 'surface_association'),
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('t', 'tegnsætning', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'comprehension', 'conceptual', 'surface_association'),
  ('f', 'litteratur', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
